def rodCutting(prices, fee):
    n = len(prices)
    best = [0] * (n + 1)
    for length in range(1, n + 1):
        top = prices[length - 1]
        for j in range(1, length):
            cand = prices[j - 1] - fee + best[length - j]
            if cand > top:
                top = cand
        best[length] = top
    return best[n]
